ON CONFLICT (item_key) DO UPDATE SET
    name = EXCLUDED.name,
    slot = EXCLUDED.slot,
    equip_group = EXCLUDED.equip_group,
    layer_order = EXCLUDED.layer_order,
    asset_path = EXCLUDED.asset_path,
    is_default = EXCLUDED.is_default,
    is_starter = EXCLUDED.is_starter,
    is_tradeable = EXCLUDED.is_tradeable,
    is_sellable = EXCLUDED.is_sellable,
    rarity = EXCLUDED.rarity,
    base_price = EXCLUDED.base_price,
    release_status = EXCLUDED.release_status,
    metadata = public.avatar_items.metadata || EXCLUDED.metadata,
    category = EXCLUDED.category,
    parts = EXCLUDED.parts,
    dyes = EXCLUDED.dyes,
    hides = EXCLUDED.hides,
    occupies = EXCLUDED.occupies,
    stack_order = EXCLUDED.stack_order
WHERE public.avatar_items.art_version = 3;

-- Items no longer in pixel-avatar/ stop being sold or granted.
UPDATE public.avatar_items
SET release_status = 'retired', is_starter = FALSE, is_default = FALSE
WHERE art_version = 3 AND item_key NOT IN ('angel_wings', 'backpack', 'balloon', 'bat_buddy', 'bat_swarm', 'bat_wings', 'bathing_suit', 'beach_towel', 'bedsheet_ghost', 'black_cat', 'bobble_beanie', 'body_ghost', 'body_kid', 'body_pumpkin', 'body_scarecrow', 'body_shadowbeast', 'body_skull', 'body_werewolf', 'body_zombie', 'boots', 'bow_tie', 'butterfly_wings', 'cable_knit_sweater', 'camp_tent', 'candlestick', 'candy_pail', 'caramel_apple', 'cat_ears', 'chunky_scarf', 'cowboy_hat', 'crown', 'devil_horns', 'fireflies', 'fishing_rod', 'flannel_shirt', 'flashlight', 'flip_flops', 'freckles', 'frog', 'ghost_pup', 'ghostly_aura', 'grim_scythe', 'hair_bald', 'hair_bob', 'hair_bowl', 'hair_buzz', 'hair_cowlick', 'hair_crop', 'hair_curls', 'hair_flat_top', 'hair_fringe', 'hair_long_locks', 'hair_long_straight', 'hair_mohawk', 'hair_mop', 'hair_pigtails', 'hair_ponytail', 'hair_side_part', 'hair_space_buns', 'hair_spikes', 'hair_top_bun', 'halo', 'headphones', 'hoodie', 'hot_cider', 'jack_o_lantern_head', 'jackalope', 'jeans', 'leaf_crown', 'leaf_rake', 'little_bigfoot', 'little_ufo', 'magic_wand', 'moonlit_graveyard', 'mothman', 'mummy_wraps', 'neck_bolts', 'open_jacket', 'overalls', 'owl', 'party_hat', 'pirate_eyepatch', 'pizza_slice', 'pointy_witch_hat', 'poncho', 'puffer_vest', 'pumpkin_pal', 'pumpkin_sweater', 'purdue_beanie', 'purdue_p_cap', 'purdue_p_crewneck', 'purdue_pennant', 'rain_boots', 'raincoat', 'raven', 'reaper_hood', 'rocket_pop', 'rosy_cheeks', 'round_glasses', 'skateboard', 'skeleton_tee', 'skull_mask', 'sneakers', 'soda_pop', 'soul_lantern_px', 'spider_pal', 'stitches', 'striped_scarf', 'striped_sweater', 'sunglasses', 'swim_trunks', 'tall_top_hat', 'teddy_bear', 'tee', 'trousers', 'umbrella', 'vampire_cape', 'vampire_fangs', 'witch_broom', 'zip_jacket');
